// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi, response, batch, execution, settle } = require('./query-load-more-harness.js');

const COMPACT_ACCEPT = 'application/vnd.rdf4j.workbench-query-v2+ndjson';
const XSD = 'http://www.w3.org/2001/XMLSchema#';

function compactBatch(rows, offset = 0, hasMore = false) {
    return [
        { type: 'head', version: 2, 'term-encoding': 'array' },
        { type: 'view', id: 'tuple' },
        { type: 'vars', values: rows[0].map((_, index) => 'value' + index) },
        { type: 'namespaces', values: [{ prefix: 'ex', name: 'urn:example:' }] },
        { type: 'metadata', values: { 'result-blank-node-scope': 'response-' + offset } },
        { type: 'rows', values: rows },
        { type: 'end', metadata: {
            'result-offset': offset, 'result-limit': 2, 'result-batch-count': rows.length,
            'result-has-more': hasMore, 'result-next-offset': offset + rows.length
        } }
    ];
}

test('query execution advertises compact v2 with legacy page-stream fallback', async () => {
    const current = execution({ responses: [batch([0, 1])] });
    current.controller.submit();
    await settle();
    assert.match(current.requests[0].init.headers.Accept, new RegExp(COMPACT_ACCEPT.replace(/[.+]/g, '\\$&')));
    assert.match(current.requests[0].init.headers.Accept, /application\/vnd\.rdf4j\.workbench\+ndjson/);
    assert.equal(current.target.querySelector('.ERROR').hidden, true, 'legacy responses remain supported');
    current.controller.dispose();
});

test('compact terms stay packed in storage and render lexical values losslessly', async () => {
    const lexical = 'Åβ😃 "quotes"\n' + 'large value '.repeat(300);
    const triple = [3, [1, 'same-label'], [0, 'urn:example:p'],
        [3, [0, 'urn:example:inner'], [0, 'urn:example:p'], [2, lexical, null, 'en-GB']]];
    const row = [[0, 'urn:example:Åβ😃'], [1, 'same-label'], [2, '-01', XSD + 'integer'],
        [2, lexical, null, 'en-GB'], [2, '<strong>inert</strong>',
            'http://www.w3.org/1999/02/22-rdf-syntax-ns#XMLLiteral'], [2, '', XSD + 'string'], null, triple];
    const current = execution({ responses: [compactBatch([row, JSON.parse(JSON.stringify(row))], 0, true),
        compactBatch([JSON.parse(JSON.stringify(row)), JSON.parse(JSON.stringify(row))], 2, false)] });
    current.controller.submit();
    await settle();
    assert.equal(current.target.querySelector('.ERROR').hidden, true);
    assert.equal(current.workers.length, 1);
    const stored = current.workers[0].rows;
    assert.equal(stored.length, 2);
    assert.equal(stored.every(values => values.every(term => term === null || Array.isArray(term))), true,
        'bulk rows must not expand into a duplicate object-term graph');
    assert.equal(stored[0][1][2], 'response-0');
    assert.equal(stored[0][7][1][2], 'response-0');
    assert.equal(stored[1][1][2], 'response-0');
    assert.equal(current.target.querySelector('.query-result-layout').getAttribute('data-effective-layout'), 'records',
        'Auto selects Records for the fixture viewport with zero width');
    const layout = current.target.querySelectorAll('select').find(select => select.name === 'result-layout');
    layout.value = 'table';
    layout.trigger('change');
    await settle();
    assert.equal(current.target.querySelector('.query-result-layout').getAttribute('data-effective-layout'), 'table');
    const cells = current.target.querySelector('[data-query-row-index="0"]').children;
    assert.equal(cells[0].title, 'urn:example:Åβ😃');
    assert.equal(cells[2].title, '"-01"^^<' + XSD + 'integer>');
    assert.equal(cells[2].textContent, '-01');
    assert.equal(cells[3].getAttribute('lang'), 'en-GB');
    // XML keeps its white space in a linked value (C27), as text: the markup is not rendered.
    assert.equal(cells[4].querySelector('a.rdf-preformatted').textContent, '<strong>inert</strong>');
    assert.equal(cells[4].querySelector('strong'), null);
    assert.equal(cells[6].getAttribute('aria-label'), 'Unbound');
    assert.match(cells[7].title, /same-label/);
    assert.equal(stored[0][3][1], lexical, 'the complete literal lexical value stays unmodified in storage');
    assert.ok(cells[7].title.includes(JSON.stringify(lexical)),
        'nested RDF literal tooltips quote and escape the complete lexical value');
    current.controller.loadMore();
    await settle();
    assert.equal(stored.length, 4);
    assert.equal(stored[2][1][2], 'response-2');
    assert.notEqual(stored[0][1][2], stored[2][1][2]);
    assert.equal(current.requests[1].init.body.get('batch-offset'), '2');
    assert.equal(current.target.querySelector('.query-result-load-more').hidden, true);
    current.controller.dispose();
});

test('compact version and encoding declarations reject unsupported representations', async () => {
    const { api } = loadApi();
    for (const head of [
        { type: 'head', version: 3, 'term-encoding': 'array' },
        { type: 'head', version: 2 },
        { type: 'head', version: 2, 'term-encoding': 'object' },
        { type: 'head', version: 2, 'term-encoding': 'future' }
    ]) {
        await assert.rejects(api.consumeNdjsonResponse(response([head, { type: 'view', id: 'boolean' },
            { type: 'boolean', value: true }, { type: 'end' }])), /version|encoding/i);
    }
});

test('directed compact language literals preserve language and direction through nested rendering', async () => {
    const rtl = [2, 'مرحبا', null, 'ar', 'rtl'];
    const ltr = [2, 'hello', null, 'en', 'ltr'];
    const nested = [3, [0, 'urn:example:s'], [0, 'urn:example:p'],
        [3, [0, 'urn:example:inner'], [0, 'urn:example:p'], rtl]];
    const current = execution({ responses: [compactBatch([[rtl, ltr, nested], [rtl, ltr, nested]])] });
    current.controller.submit();
    await settle();
    assert.equal(current.target.querySelector('.ERROR').hidden, true);
    const stored = current.workers[0].rows;
    assert.deepEqual(JSON.parse(JSON.stringify(stored[0][0])), rtl);
    assert.equal(current.target.querySelector('.query-result-layout').getAttribute('data-effective-layout'), 'records',
        'Auto selects Records for the fixture viewport with zero width');
    const layout = current.target.querySelectorAll('select').find(select => select.name === 'result-layout');
    layout.value = 'table';
    layout.trigger('change');
    await settle();
    assert.equal(current.target.querySelector('.query-result-layout').getAttribute('data-effective-layout'), 'table');
    const cells = current.target.querySelector('[data-query-row-index="0"]').children;
    assert.equal(cells[0].getAttribute('lang'), 'ar');
    assert.equal(cells[0].getAttribute('dir'), 'rtl');
    assert.equal(cells[1].getAttribute('lang'), 'en');
    assert.equal(cells[1].getAttribute('dir'), 'ltr');
    assert.match(cells[0].textContent, /@ar--rtl/);
    assert.match(cells[1].textContent, /@en--ltr/);
    assert.match(decodeURIComponent(cells[0].querySelector('a').getAttribute('href')), /@ar--rtl/);
    assert.match(decodeURIComponent(cells[2].querySelector('a').getAttribute('href')), /@ar--rtl/);
    current.controller.dispose();
});

test('compact RDF tags validate arity and RDF triple positions before storage', async () => {
    const { api } = loadApi();
    for (const invalid of [
        [4, 'unknown'], [0, 42], [0, 'urn:p', 'extra'], [1, 'blank', 'wire-scope'],
        [2, 'value', null], [2, 'value', XSD + 'string', 'en'],
        [2, 'value', null, 7], [2, 'value', null, 'ar', 'auto'], [2, 'value', null, 'ar', '--rtl'],
        [2, 'value', null, 'ar', 'RTL'], [2, 'value', null, 'ar', null],
        [2, 'value', XSD + 'string', 'ar', 'rtl'], [2, 'value', null, 'ar', 'rtl', 'extra'],
        [3, [2, 'literal', XSD + 'string'], [0, 'urn:p'], [0, 'urn:o']],
        [3, [0, 'urn:s'], [1, 'not-an-iri'], [0, 'urn:o']],
        [3, [0, 'urn:s'], [0, 'urn:p'], null]
    ]) {
        const state = new api.QueryResultState();
        await assert.rejects(api.consumeNdjsonResponse(response(compactBatch([[invalid], [null]])), {
            onRecord(record) { state.accept(record); }
        }), /typed RDF|compact.*term|RDF term/i);
        assert.equal(state.rowCount, 0);
    }
});
